#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int countConsistentStrings(string allowed, vector<string>& words) {
        unordered_set<char> allow(allowed.begin(), allowed.end());
        int ans = 0;
        for (const auto& w : words) {
            bool ok = true;
            for (char c : w) {
                if (allow.find(c) == allow.end()) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countConsistentStrings(String allowed, String[] words) {
        Set<Character> allow = new HashSet<>();
        for (char c : allowed.toCharArray()) allow.add(c);
        int ans = 0;
        for (String w : words) {
            boolean ok = true;
            for (char c : w.toCharArray()) {
                if (!allow.contains(c)) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
}

/**
 * @param {string} allowed
 * @param {string[]} words
 * @return {number}
 */
var countConsistentStrings = function(allowed, words) {
    const allow = new Set(allowed);
    let ans = 0;
    for (const w of words) {
        let ok = true;
        for (let i = 0; i < w.length; ++i) {
            if (!allow.has(w[i])) { ok = false; break; }
        }
        if (ok) ans++;
    }
    return ans;
};
